import { Page, Section, Text, BulletList, Table, Diagram, Sequence, Steps, Select, Segmented, Input, Toggle, Status, TableOfContents, useState, useMemo } from "grok/canvas";
import type { ReactNode } from "grok/canvas";

type D = "B" | "I" | "A";
type Q = [string, D, string, string, string, string?, string?];

const T: Record<string, string> = {
  aws: "AWS cloud",
  iac: "Infrastructure as code",
  k8s: "Docker and Kubernetes",
  cicd: "CI/CD and release management",
  obs: "Observability and RCA",
  msg: "Messaging: Kafka and RabbitMQ",
  sec: "Security and authentication",
  ai: "AI-assisted engineering and MCP",
  sd: "System design",
};
const ORDER = ["aws", "iac", "k8s", "cicd", "obs", "msg", "sec", "ai", "sd"];
const DL: Record<D, string> = { B: "Basic", I: "Intermediate", A: "Advanced" };

const QS: Q[] = [
  // AWS
  ["aws", "B", "ECS vs Lambda vs EC2: when do you use each?", "EC2: virtual machines you manage; full control, good for legacy or special software.|ECS: run Docker containers as long-running services (on EC2 or Fargate); good for APIs and workers with steady traffic.|Lambda: functions triggered by events, pay per invocation, scale to zero; good for event handlers, glue and spiky workloads, with a 15-minute limit and cold starts.|In IRT we ran microservices on ECS behind load balancers and used Lambda for event-driven pieces.", "EC2 = rent a house, ECS = rent furnished rooms, Lambda = hotel by the hour.", "compute"],
  ["aws", "I", "Explain the ECS building blocks.", "Cluster: logical group of capacity (EC2 instances or Fargate).|Task definition: the blueprint, like a docker-compose file: image, CPU/memory, env vars, ports, IAM task role, log config.|Task: a running instance of the definition; Service: keeps N tasks running, replaces unhealthy ones, registers them with a load balancer target group, and scales.|Images come from ECR; logs go to CloudWatch.", "Blueprint (task def), workers (tasks), manager (service), building (cluster).", "ecs"],
  ["aws", "I", "What does API Gateway do?", "A managed front door for APIs: routing to Lambda, ECS/HTTP backends or AWS services.|Handles authentication (JWT/Cognito authorizers, Lambda authorizers, IAM), throttling, quotas, request validation, CORS and stages.|REST APIs (feature rich) vs HTTP APIs (cheaper, faster) vs WebSocket APIs.|Logs and metrics go to CloudWatch.", "API Gateway = hotel reception: checks ID, directs you, limits crowds."],
  ["aws", "I", "What are Lambda cold starts and how do you reduce them?", "A cold start happens when AWS must create a new execution environment: download code, start the runtime, run init code.|.NET can have larger cold starts; reduce with smaller packages, native AOT or ReadyToRun, SnapStart where supported, and lighter init.|Provisioned concurrency keeps environments warm for latency-critical paths.|Reuse SDK clients and connections outside the handler.", "Cold start = starting a car in winter; provisioned concurrency = engine kept running."],
  ["aws", "I", "How do you model data in DynamoDB?", "Start from access patterns, not entities.|Partition key spreads data and must have high cardinality to avoid hot partitions; sort key enables range queries (begins_with, between).|GSIs and LSIs support extra access patterns; single-table design stores related items together.|Use conditional writes for optimistic concurrency, TTL for expiry, Streams to trigger Lambdas.", "Partition key = which drawer, sort key = order inside the drawer."],
  ["aws", "I", "What caching strategies do you know (ElastiCache)?", "Cache-aside (lazy loading): read cache, on miss read DB and populate; most common.|Write-through: write to cache and DB together; read-heavy consistency.|Write-behind: write to cache, flush to DB later; fast but risky.|Set TTLs, invalidate on change, avoid stampedes with locking or jitter, never cache sensitive patient data without controls.", "Cache-aside = check the fridge, if empty go to the shop and refill.", "cache"],
  ["aws", "B", "ALB vs NLB?", "Application Load Balancer: layer 7 (HTTP/HTTPS), path/host routing, header rules, works with ECS target groups and WAF.|Network Load Balancer: layer 4 (TCP/UDP), ultra-low latency, static IPs, millions of requests per second.|Both do health checks and spread traffic across availability zones.|For REST microservices on ECS, ALB is the usual choice.", "ALB reads the letter (HTTP), NLB only reads the envelope (TCP)."],
  ["aws", "B", "What is S3 used for, and what are presigned URLs?", "S3 is durable object storage: files, exports, backups, static sites, build artifacts.|Storage classes trade cost for access speed; lifecycle rules move or expire objects.|A presigned URL gives time-limited access to upload or download one object without exposing credentials.|Block public access, encrypt with SSE-KMS, and use bucket policies with least privilege.", "Presigned URL = a one-time visitor pass that expires."],
  ["aws", "I", "How do you apply IAM least privilege?", "Give each service its own IAM role (ECS task role, Lambda execution role) with only the actions and resources it needs.|No long-lived access keys in code; use roles and Secrets Manager or Parameter Store.|Use conditions, resource ARNs, and review with IAM Access Analyzer.|Separate accounts or environments for dev, validation and production.", "Give a key to one room, not the master key."],
  ["aws", "I", "Describe a typical AWS network layout for microservices.", "A VPC across at least two availability zones.|Public subnets hold the load balancer and NAT gateway; private subnets hold ECS tasks, Lambdas in VPC, RDS and ElastiCache.|Security groups allow only needed ports (ALB to service, service to DB).|VPC endpoints for S3 and DynamoDB keep traffic off the internet.", "Public lobby, private offices, guards (security groups) at each door.", "vpc"],
  // IaC
  ["iac", "B", "What is infrastructure as code and why use it?", "Cloud resources are defined in versioned files (CloudFormation, Terraform) instead of clicking in the console.|Benefits: repeatable environments, code review, audit trail, drift detection, easy rebuild and disaster recovery.|Very important in regulated work: every change is traceable.|Changes flow through the same CI/CD as application code.", "IaC = the architect's blueprint, not hand-built each time."],
  ["iac", "I", "CloudFormation vs Terraform?", "CloudFormation: AWS-native, JSON/YAML templates, state managed by AWS as stacks, change sets, rollback on failure.|Terraform: multi-cloud HCL, providers for many services, explicit state file, plan/apply workflow, rich module ecosystem.|CloudFormation gets new AWS features via AWS; Terraform is better when you mix clouds or SaaS.|I have used both for ECS, Lambda, API Gateway, DynamoDB and RDS resources.", "CloudFormation = AWS's own language; Terraform = translator for every cloud.", "cfntf"],
  ["iac", "I", "What is Terraform state and how do you manage it?", "State maps resources in code to real resources and stores attributes.|Keep it remote (S3 backend with DynamoDB locking or Terraform Cloud), encrypted, never in Git.|Locking prevents two applies at once; workspaces or separate states per environment.|Use `terraform import` for existing resources and `state mv` for refactors.", "State = Terraform's memory; lock it so two people do not edit at once."],
  ["iac", "I", "Describe the Terraform workflow.", "Write HCL, then `terraform init` to download providers and configure the backend.|`terraform plan` shows the diff; review it in the pull request.|`terraform apply` makes the change after approval.|Run from the pipeline, not laptops; detect drift with scheduled plans.", "Write, Init, Plan, Apply: measure twice, cut once.", "tfflow"],
  ["iac", "A", "What is drift and how do you avoid it?", "Drift is when real infrastructure no longer matches code, usually from manual console changes.|Detect: CloudFormation drift detection or scheduled `terraform plan`.|Prevent: restrict console write access, all changes through pipelines, tag resources managed by IaC.|Fix: import the change into code or re-apply code.", "Drift = someone moved the furniture without updating the floor plan."],
  // Docker / K8s
  ["k8s", "B", "Image vs container; what is a Dockerfile?", "An image is an immutable, layered template; a container is a running instance of it.|A Dockerfile lists steps: base image, copy files, restore, build, set entrypoint.|Layers are cached, so order instructions from least to most frequently changing.|Containers make dev, test and production behave the same.", "Image = recipe card, container = the cooked dish."],
  ["k8s", "I", "How do you write a production Dockerfile for a .NET service?", "Multi-stage build: SDK image to restore and publish, small runtime (aspnet or chiseled) image to run.|Copy csproj files and restore first to cache dependencies.|Run as non-root, expose the port, add a health check endpoint, no secrets in the image.|Tag images with the build/release version and scan them for vulnerabilities.", "Build in the workshop, ship only the finished product.", "docker"],
  ["k8s", "I", "Explain the main Kubernetes objects.", "Pod: smallest unit, one or more containers sharing network and storage.|Deployment: desired number of pod replicas, rolling updates and rollbacks (via ReplicaSets).|Service: stable virtual IP/DNS that load-balances across pods; Ingress: HTTP routing from outside.|ConfigMap and Secret for configuration; Namespace for isolation; HPA for autoscaling.", "Pod = a room, Deployment = landlord keeping N rooms ready, Service = the building's reception.", "k8s"],
  ["k8s", "I", "What goes in a Kubernetes Deployment YAML?", "apiVersion, kind: Deployment, metadata (name, labels).|spec.replicas, spec.selector matching pod labels, and spec.template with containers: image, ports, env, resources (requests/limits).|Liveness and readiness probes; strategy (RollingUpdate with maxSurge/maxUnavailable).|A separate Service YAML selects pods by label.", "Who am I (metadata), how many (replicas), what to run (template), am I healthy (probes)."],
  ["k8s", "I", "Liveness vs readiness vs startup probes?", "Readiness: is the pod ready for traffic? If not, it is removed from the Service endpoints.|Liveness: is it stuck? If it fails, Kubernetes restarts the container.|Startup: gives slow-starting apps time before liveness checks begin.|In ASP.NET Core expose /health/ready and /health/live with Health Checks.", "Readiness = open sign on the shop; liveness = pulse check."],
  ["k8s", "I", "ConfigMap vs Secret; how do you handle configuration in containers?", "ConfigMap holds non-sensitive config; Secret holds sensitive values (base64, not encrypted by default; enable encryption at rest or use an external secret store).|Inject as environment variables or mounted files.|Keep the same image across environments and change only config.|On AWS, prefer Secrets Manager or Parameter Store integrated with ECS or the cluster.", "Same suitcase (image), different labels (config) per trip."],
  ["k8s", "A", "How does autoscaling work in Kubernetes and ECS?", "Kubernetes HPA scales pod replicas on CPU, memory or custom metrics; Cluster Autoscaler or Karpenter adds nodes.|ECS Service Auto Scaling uses target tracking (for example 60 percent CPU) or step scaling from CloudWatch alarms.|Set requests/limits properly or scaling decisions are wrong.|Scale on queue depth for consumers.", "Thermostat: keep the temperature (CPU) at the target by adding heaters (pods)."],
  ["k8s", "B", "Docker vs Kubernetes vs ECS?", "Docker builds and runs containers on one host.|Kubernetes orchestrates containers across many hosts: scheduling, healing, scaling, service discovery; portable but complex.|ECS is AWS's simpler managed orchestrator, tightly integrated with IAM, ALB and CloudWatch.|We used Docker for images, Kubernetes YAML for some workloads and ECS on AWS.", "Docker = a shipping container; Kubernetes/ECS = the port that moves thousands of them."],
  // CI/CD
  ["cicd", "B", "CI vs continuous delivery vs continuous deployment?", "Continuous integration: every merge builds and runs tests automatically.|Continuous delivery: every build is releasable; production deploy is a manual approval.|Continuous deployment: every passing change goes to production automatically.|In a regulated GxP product we do continuous delivery with formal approval gates.", "CI = always compiles, CD = always shippable, Deploy = always shipped."],
  ["cicd", "I", "Describe your Azure DevOps pipeline and release flow.", "Build pipeline (YAML): restore, build, unit tests, SonarQube analysis and quality gate, publish artifacts and Docker images.|Release: deploy the same artifact through environments: FV (validation), TechOps, UAT, then production.|Each stage has approvals and checks; Ansible, Python and Shell scripts run the multi-node installs.|Release is merged and tagged so every environment is traceable to one version.", "Build once, promote the same box through every gate.", "release"],
  ["cicd", "I", "YAML pipelines vs classic release pipelines in Azure DevOps?", "YAML pipelines live in the repo: versioned, reviewed, templated, multi-stage.|Classic Releases are configured in the UI with visual stages and approvals; common on on-prem Azure DevOps Server.|YAML supports environments with approvals and checks; templates remove duplication.|Our MCP server talks to Azure DevOps Server APIs to trigger and monitor both builds and releases.", "YAML = recipe in the cookbook; classic = recipe on a sticky note."],
  ["cicd", "I", "What branching and tagging strategy do you follow?", "Feature branches off main/develop with pull requests, reviews and build validation.|Release branches cut for a version; hotfix branches from the release tag.|Tags mark exactly what was deployed (semantic version), which auditors and support rely on.|I owned merging and tagging releases across application, APIs, database and UI.", "Branches are drafts, tags are the printed edition."],
  ["cicd", "I", "What role did Ansible play, and what is idempotency in it?", "Ansible automates configuration and installs over SSH or WinRM with no agent, using playbooks and roles in YAML.|We used Ansible with Python and Shell scripts to install releases across multiple nodes.|Idempotent tasks can run many times and leave the same end state (for example 'ensure service is running').|Inventory files define the nodes per environment.", "Ansible = a checklist robot; running it twice does not do the job twice."],
  ["cicd", "I", "Blue-green vs canary vs rolling deployments?", "Rolling: replace instances gradually; no extra capacity, but mixed versions run for a while.|Blue-green: deploy to an idle copy, switch traffic at once; instant rollback, double resources.|Canary: send a small percentage of traffic to the new version, watch metrics, then expand.|Choose by risk, cost and how easily you can roll back.", "Rolling = change tyres one at a time; blue-green = second car ready; canary = send one bird first.", "deploy"],
  ["cicd", "A", "How do you plan rollback for a release that includes database changes?", "Keep schema changes backward compatible (expand-contract) so the previous app version still works.|Keep the previous artifact and release tag ready to redeploy; feature flags to switch off new behaviour.|Back up before risky migrations; have tested down scripts where feasible.|Define go/no-go checks and smoke tests after deployment.", "Always leave a ladder down before you climb."],
  ["cicd", "A", "How is release management different in a regulated GxP environment?", "Every change links to a requirement or defect, with impact assessment, review and test evidence.|Formal environments and sign-offs: FV, TechOps, UAT, production; segregation of duties.|Validated, repeatable deployment scripts and an audit trail of who deployed what and when.|Automation helps: our MCP-driven deployments kept the steps consistent and logged, while humans kept approvals.", "Regulated release = a flight checklist with signatures."],
  // Observability
  ["obs", "B", "What are logs, metrics and traces?", "Logs: detailed event records (what happened), structured JSON in CloudWatch Logs.|Metrics: numbers over time (latency, error rate, CPU, queue depth) for dashboards and alarms.|Traces: the path of one request across services, joined by a trace or correlation id.|Together they let you detect, locate and explain issues.", "Metrics say something is wrong, traces say where, logs say why.", "obs3"],
  ["obs", "I", "How do you use CloudWatch and Grafana?", "CloudWatch Logs for application logs with Logs Insights queries; metrics from ECS, Lambda, ALB, RDS; alarms to notify on thresholds.|Grafana dashboards combine CloudWatch and other sources into one view for services and releases.|Alert on symptoms users feel (error rate, latency), not just CPU.|After a release, watch dashboards for regressions.", "CloudWatch collects, Grafana tells the story."],
  ["obs", "I", "What are the golden signals?", "Latency: how long requests take (track p95/p99, not just average).|Traffic: requests per second or messages per second.|Errors: failure rate (5xx, exceptions, dead-lettered messages).|Saturation: how full the system is (CPU, memory, connection pool, queue depth).", "L-T-E-S: Late, Traffic, Errors, Saturation."],
  ["obs", "A", "How do you do root-cause analysis for a production issue?", "Stabilise first: mitigate impact (rollback, scale, failover) and communicate.|Gather evidence: timeline, dashboards, logs by correlation id, recent changes.|Form and test hypotheses; use 5 Whys to go past the symptom to the real cause.|Fix, add monitoring or tests so it cannot recur, and write a blameless post-mortem.", "Stop the bleeding, find the wound, prevent the next one.", "rca"],
  ["obs", "I", "What makes a good alert?", "Actionable: someone knows what to do when it fires; link a runbook.|Based on user impact and sustained thresholds to avoid noise.|Routed to the right owner with severity.|Reviewed regularly; delete alerts nobody acts on.", "If an alert wakes you up, it must need you."],
  // Messaging
  ["msg", "I", "Kafka vs RabbitMQ?", "RabbitMQ: a message broker with exchanges and queues; messages are removed after acknowledgement; flexible routing; great for task queues and commands.|Kafka: a distributed, partitioned, append-only log; messages are retained and can be replayed; very high throughput; consumer groups track offsets.|Ordering: Kafka per partition; RabbitMQ per queue with one consumer.|Use RabbitMQ for work distribution, Kafka for event streams and integrations needing replay.", "RabbitMQ = post office that delivers and forgets; Kafka = a diary everyone can re-read.", "kafkarabbit"],
  ["msg", "I", "Explain Kafka topics, partitions and consumer groups.", "A topic is split into partitions; each is an ordered log with offsets.|Producers choose a partition by key, so all events for one key (for example a study id) stay in order.|In a consumer group, each partition is read by exactly one consumer, so parallelism is limited by partition count.|Consumers commit offsets; replication across brokers gives durability.", "Topic = highway, partitions = lanes, consumer group = toll booths, one per lane.", "kafka"],
  ["msg", "I", "RabbitMQ exchange types?", "Direct: routes by exact routing key.|Topic: routes by pattern (`shipment.*.created`).|Fanout: broadcasts to all bound queues.|Headers: routes by header values. Producers publish to exchanges, never directly to queues.", "Direct = named letter, Topic = postcode pattern, Fanout = flyer to every house.", "rabbit"],
  ["msg", "A", "What are publisher confirms and how did they fix the RabbitMQ outage?", "By default a publish is fire-and-forget: if the broker is under pressure, restarts or a connection drops, messages can be lost silently.|With publisher confirms the channel is put in confirm mode and the broker acks (or nacks) each message once it is safely handled (persisted for durable queues).|The publisher tracks unconfirmed messages and retries or alerts on nack or timeout.|Combined with durable queues, persistent messages and consumer manual acks, this gives at-least-once delivery.|Situation: [one evening in mid-2024] a production RabbitMQ node hit its memory high watermark while a [large vendor shipment-status file] was being loaded. The broker blocked publishers and dropped some connections, and for [about 40 minutes] shipment-status updates from the vendor integration service never reached the shipment service. Randomization and dispensing were not affected.|Task: I was on the support rotation, so I had to restore the flow, find the root cause and stop it happening again.|Action: Grafana showed the integration service publishing normally while the incoming rate on the shipments queue had dropped to zero. The RabbitMQ management UI showed the memory alarm and blocked connections. The app logs had no errors because we published with BasicPublish and no confirms. To recover, I scaled out consumers to drain the backlog and replayed the missed window from the vendor files, which was safe because consumers upsert status by shipment id. The permanent fix was publisher confirms with tracking of unconfirmed messages, retry with backoff on nack or timeout, persistent messages on durable queues, and alerts on nacks, memory alarms and blocked connections.|Result: the replay recovered all [about 1,200] updates the same evening. In the [12 months] since there has been no silent loss, and a later broker restart produced [a few dozen] nacks that were retried automatically and showed up in alerts. The full STAR version is in part 3.", "Publisher confirm = registered post with a delivery receipt.", "confirms", "Why did messages vanish without any error?::BasicPublish returns once the bytes are written to the socket. If the connection drops before the broker stores the message, the publisher never finds out. Without confirms there is no signal at all.||Do confirms slow publishing down?::Waiting synchronously after every message would. We track confirms asynchronously against delivery tags, which cost about [5 percent] throughput, an acceptable price for no loss.||Why not switch to Kafka?::RabbitMQ fits our command and work-queue flows. The problem was a missing delivery guarantee, not the broker, and Kafka would need the same discipline (acks=all, retries, idempotent consumers)."],
  ["msg", "I", "At-most-once, at-least-once, exactly-once delivery?", "At-most-once: no retries; messages may be lost.|At-least-once: retries until acknowledged; duplicates possible, so consumers must be idempotent. The usual practical choice.|Exactly-once: no loss and no duplicates; only within limits (Kafka transactions) or achieved effectively through idempotency.|Design for at-least-once plus idempotent consumers.", "Better to get the letter twice and ignore one than never get it."],
  ["msg", "I", "How do you make a consumer idempotent?", "Give every message a unique id; store processed ids (inbox table) and skip repeats.|Use natural idempotency: upserts, 'set status to shipped' rather than 'increment'.|Make the processed-id insert and the business update in the same transaction.|Retry with backoff, then dead-letter after N attempts.", "Stamp each letter 'done' so you never act on it twice."],
  ["msg", "I", "What is a dead-letter queue?", "Messages that keep failing (or expire, or are rejected) are moved to a separate DLQ instead of blocking the main queue.|Alert on DLQ depth, inspect, fix the cause, then replay.|In RabbitMQ configure a dead-letter exchange; in Kafka publish to a retry or DLT topic.|Never silently drop clinical data messages.", "DLQ = the lost-and-found box."],
  ["msg", "A", "What is the transactional outbox pattern?", "Problem: you update the database and publish an event; if one succeeds and the other fails, systems disagree.|Solution: in the same DB transaction, write the business change and an outbox row.|A background relay reads the outbox and publishes to Kafka or RabbitMQ, marking rows sent (retry until confirmed).|Consumers stay idempotent because the relay may publish twice.", "Write the letter in the same notebook as the change; a postman collects it later.", "outbox"],
  // Security
  ["sec", "B", "Authentication vs authorization?", "Authentication: who are you (login, token validation).|Authorization: what are you allowed to do (roles, claims, policies, resource checks like 'can this user see this study?').|In ASP.NET Core: UseAuthentication then UseAuthorization; [Authorize(Policy = ...)].|401 = not authenticated, 403 = authenticated but not allowed.", "Authentication = passport check, authorization = boarding pass for a specific seat."],
  ["sec", "I", "What is a JWT and how is it validated?", "Three base64url parts: header (algorithm), payload (claims: sub, roles, exp, iss, aud), signature.|The API validates signature with the issuer's key, plus issuer, audience, expiry and not-before.|It is signed, not encrypted: never put secrets or PHI in it.|Keep access tokens short-lived; use refresh tokens to get new ones.", "JWT = a sealed wristband: anyone can read it, nobody can forge it.", "jwt"],
  ["sec", "I", "Explain the OAuth 2.0 / OpenID Connect authorization code flow with PKCE.", "The app redirects the user to the identity provider with a code challenge.|User logs in (SSO); IdP redirects back with a short-lived authorization code.|The app exchanges the code plus the code verifier for tokens: access token (OAuth, for APIs) and ID token (OIDC, who the user is).|The app calls the API with the access token; the API validates it. Client credentials flow is used for service-to-service.", "Code is a cloakroom ticket; only the person with the matching stub (verifier) gets the coat.", "oauth"],
  ["sec", "A", "Why is logout hard with tokens, and how did you fix token-based logout?", "A JWT stays valid until it expires even after the user clicks logout, because the server is stateless.|Fixes: short access-token lifetimes; revoke refresh tokens server-side on logout; a denylist of token ids (jti) checked in middleware until expiry; clear cookies; end the IdP session for SSO.|Also invalidate on password change or role change.|Situation: a [2024 security review] found that in one IRT module a JWT access token captured before logout could still call the APIs until it expired, [60 minutes] later.|Task: make logout really end access, without adding noticeable latency to every API call.|Action: I cut the access-token lifetime to [15 minutes]. On logout the server now revokes the refresh token, which is stored server-side, and writes the access token's jti to a denylist in ElastiCache (Redis) with a TTL equal to the token's remaining life. The JWT bearer OnTokenValidated event checks that denylist with one key lookup. Logout also clears the auth cookies and calls the identity provider's end-session endpoint so the SSO session ends too. I added a unit test and a Playwright test that replays an old token after logout and expects 401.|Result: the retest passed, old tokens are rejected immediately after logout, and the denylist check adds about [1 ms] per request. The fix went through review and the regulated release process.", "Logout must take the wristband back, not just say goodbye.", "", "Why not just use server-side sessions instead of JWT?::That works too, but the APIs are called by several services and scale out behind a load balancer. Keeping JWTs stateless and adding a small denylist only for logged-out tokens was the smaller, safer change.||What if Redis is unavailable?::We alert on it and fail closed for that check, returning 401 so the user logs in again, because accepting a revoked token is worse than an extra login. The short token lifetime limits exposure either way.||Why a TTL on denylist entries?::Once the token's own expiry passes, it is rejected anyway, so the entry can expire. That keeps the denylist small."],
  ["sec", "A", "What causes 'request header too long' with SSO cookies, and how did you fix it?", "Servers limit total request header size (IIS, Kestrel, load balancers, often 8 to 16 KB).|SSO tokens with many claims or groups, stored in cookies, can exceed it; chunked auth cookies add up across apps on the same domain.|Fixes: trim claims, store the session server-side and keep only a reference in the cookie, scope cookie domain and path, clean stale cookies; raising limits is a last resort.|Situation: in [2024] some users, mostly [study managers with access to many studies], got 'HTTP 400: the size of the request headers is too long' straight after SSO login, while other users were fine. We had [about 30] support tickets over [two weeks].|Task: find out why only some users failed and fix it permanently.|Action: I reproduced it with a test user given many role and study groups. ASP.NET Core cookie authentication was storing every role and group claim in the auth cookie and splitting it into [5] chunks of about [13 KB] in total. Together with other apps' cookies on the same parent domain, the Cookie header passed the [16 KB] request-header limit of the IIS/http.sys front end. I removed group and role claims from the cookie by storing the authentication ticket server-side through an ITicketStore, so the cookie holds only a session key, and loaded study-level permissions per request through claims transformation with caching. I also narrowed the cookie path and domain so sibling apps' cookies were not sent, and cleared old cookie names.|Result: the auth cookie fell from [about 13 KB to under 1 KB], affected users could log in again, and I added a regression test with a user in [200+] groups. We did not raise the server limits.", "Do not carry your whole wardrobe in your pocket; carry the locker key.", "", "Why not just increase the header size limit?::It only moves the problem. The next user with more groups fails again, and every request carries a big cookie, which wastes bandwidth and exposes more data. Shrinking the cookie fixes the cause.||What is an ITicketStore?::An ASP.NET Core cookie-auth extension point that stores the authentication ticket server-side (for example in Redis or SQL) and puts only a key in the cookie.||Did loading permissions per request slow things down?::They are cached per user for a short time, so the cost was negligible, and permission changes take effect faster than with claims baked into a cookie."],
  ["sec", "I", "What is reverse tabnabbing?", "A page opened with target=_blank gets window.opener and can redirect the original tab to a phishing page.|Fix: rel=\"noopener noreferrer\" on links (modern browsers default noopener for _blank, but be explicit), and `window.open(url, '_blank', 'noopener')`.|Also set Cross-Origin-Opener-Policy.|I fixed this across the IRT UI.", "Never let the new tab hold the remote control of the old tab."],
  ["sec", "I", "Which OWASP Top 10 risks matter most for APIs and how do you prevent them?", "Broken access control: check authorization per resource, not just per endpoint.|Injection: parameterised queries, validation.|Cryptographic failures: TLS everywhere, encrypt at rest, no secrets in code.|Security misconfiguration, vulnerable components (scan dependencies, SonarQube), logging and monitoring failures, SSRF.", "A-I-C-M: Access, Injection, Crypto, Misconfig."],
  ["sec", "I", "XSS vs CSRF?", "XSS: attacker's script runs in your site; prevent with output encoding, sanitising HTML, Content Security Policy, HttpOnly cookies.|CSRF: attacker's site makes the user's browser send an authenticated request to your site; prevent with SameSite cookies, anti-forgery tokens, or bearer tokens in headers.|APIs using Authorization headers are not exposed to classic CSRF.|Both matter for a cookie-based SSO web app.", "XSS = intruder inside the house; CSRF = forged letter signed with your name."],
  ["sec", "I", "How do you manage secrets?", "Never in source code or images; scan repos for leaks.|Use AWS Secrets Manager / Parameter Store, Azure Key Vault, or pipeline secret variables.|Rotate regularly; give access through IAM roles.|For the MCP server, credentials (Azure DevOps tokens) are read from the user's environment or secure store, never hard-coded or logged.", "Secrets live in a vault, not under the doormat."],
  // AI / MCP
  ["ai", "B", "What is the Model Context Protocol (MCP)?", "An open protocol that standardises how AI applications (hosts like Claude, Cursor, Copilot) connect to external tools and data.|An MCP server exposes tools (actions), resources (data) and prompts; the client in the host discovers them and the model decides when to call them.|Transports: stdio for local servers, streamable HTTP for remote.|It replaces one-off integrations with one reusable server per system.", "MCP = USB-C for AI tools.", "mcp"],
  ["ai", "A", "How did you design your MCP server with about 77 tools?", "Purpose: let AI agents run build, release and multi-node deployment operations on on-prem Azure DevOps Server.|Tools grouped by domain: builds (queue, status, logs), releases (create, approve, deploy stage), deployments across nodes, artifacts and environment checks.|Each tool has a clear name, a precise description and a typed JSON schema so the model picks it correctly; outputs are concise and structured.|Packaged as a reusable tool teammates install and run; result: deployment time cut from 6 hours to 2 and people per deployment from 6 to 1.", "77 tools in labelled drawers: Build, Release, Deploy, Verify.", "mcparch"],
  ["ai", "A", "How do you make an MCP server safe to use?", "Least privilege: it uses the caller's own credentials and permissions; no shared admin token.|Separate read-only tools from write tools; destructive or production actions require explicit confirmation and keep human approval gates.|Validate all inputs against schemas and allow-lists (environments, pipelines); add timeouts and idempotency.|Log every tool call for audit; never return secrets in outputs.", "AI may push the buttons, but humans hold the keys to production."],
  ["ai", "I", "What makes a good tool definition for an AI agent?", "A specific, verb-first name (queue_build, get_release_status).|A description that says when to use it and what it returns, with examples.|A small, typed input schema with enums and defaults; required fields only when needed.|Compact, structured output and clear error messages the model can act on; fewer, well-scoped tools beat many overlapping ones.", "Tools are written for a new colleague who reads nothing but the label."],
  ["ai", "I", "How do you use GitHub Copilot and Cursor day to day?", "Inline completions for boilerplate, tests and mappings; chat for explaining unfamiliar code.|Agent mode in Cursor for multi-file changes, refactors and upgrade chores, with project rules for our conventions.|Generating unit tests and test data, drafting SQL and pipeline YAML, summarising logs.|Always review, build and test the output; I own every line that I commit.", "AI is my pair programmer, not my reviewer of last resort."],
  ["ai", "A", "How do you evaluate AI-generated code for security and accuracy?", "Read it as a reviewer would: logic, edge cases, error handling, async correctness.|Security: injection, authorization checks, secrets, unsafe deserialisation, hallucinated or outdated packages and APIs.|Verify with compilation, unit tests, SonarQube and running it; check docs for APIs it used.|Keep sensitive data out of prompts; follow company policy on approved tools.", "Trust, but compile, test and scan."],
  ["ai", "I", "What prompt engineering techniques do you use?", "Give role, context and the exact goal; include constraints (framework version, style, no new packages).|Provide examples of input and output (few-shot) and the expected format.|Break complex tasks into steps; ask for a plan first, then the code.|Iterate: give the model compiler errors or failing tests as feedback.", "R-C-G-F: Role, Context, Goal, Format."],
  ["ai", "I", "Explain RAG (retrieval-augmented generation).", "Ingest documents, split into chunks, create embeddings and store them in a vector index.|At query time embed the question, retrieve the most relevant chunks, and add them to the prompt.|The LLM answers grounded in those chunks, ideally citing sources.|Benefits: current, private knowledge without fine-tuning; quality depends on chunking, retrieval and evaluation.", "RAG = open-book exam: find the right page, then answer.", "rag"],
  ["ai", "I", "What is agentic orchestration (AutoGen, Claude Code)?", "An agent is an LLM in a loop: plan, call tools, observe results, repeat until the goal is met.|Orchestration coordinates one or more agents (planner, executor, reviewer) and their tools, with limits on steps and permissions.|AutoGen provides multi-agent conversations; Claude Code is a coding agent in the terminal that can use MCP servers.|I apply it to engineering workflows such as deployments and code tasks, not ML research.", "Agent loop: Think, Act, Observe, repeat.", "agent"],
  ["ai", "I", "Azure OpenAI vs using a model provider directly?", "Azure OpenAI runs models inside the company's Azure tenant: enterprise security, private networking, data not used for training, regional compliance, Azure AD auth.|Direct APIs may get new models sooner and can be simpler for prototypes.|For a regulated healthcare company, enterprise controls usually decide.|Either way: monitor cost, rate limits and content filters.", "Same engine, but Azure puts it in the company garage."],
  ["ai", "A", "How do you reduce hallucinations and errors from LLM features?", "Ground the model: RAG, tool calls for facts, clear instructions to say 'I do not know'.|Constrain output with schemas (JSON mode, function calling) and validate it in code.|Evaluate with test sets and human review; log prompts and outputs.|Keep a human in the loop for high-impact actions.", "Give the model a map (context), a fence (schema) and a guard (validation)."],
  ["ai", "I", "How did you get the team to adopt AI tools?", "Started with a real pain point: slow, manual, multi-person deployments.|Built the MCP server, packaged it so it was easy to install, and demoed it in team sessions.|Wrote short guides and prompt examples; paired with teammates on first runs.|Collected feedback and added tools people asked for.|Situation: once the CIRT MCP server worked for my own deployments, teammates still used the old manual, multi-person process out of habit and caution.|Task: get the team using it safely, without forcing it.|Action: I ran a [30-minute] live demo at a sprint demo using a real UAT deployment. I wrote a README with setup steps and [10] example prompts, paired with the first [4] engineers on their first deployment, and kept a team chat thread for questions. I added the tools people asked for, such as fetching logs for a failed release step.|Result: within [about two months] most of our team's release deployments ran through it, deployment time went from 6 hours to 2, and people per deployment from 6 to 1.", "Solve a real pain, make it easy, show it, support it.", "", "Was there any resistance?::Yes, mainly worry that an AI agent would do something wrong in a regulated environment. Showing that it uses each person's own permissions, asks for confirmation before risky steps and keeps the existing approvals removed most of it.||What if the agent makes a mistake during a deployment?::Tools are scoped and validated, production steps need human approval, and every tool call is logged. A failed step stops the run with a clear report, and the person re-runs only that step after fixing the cause."],
  // System design
  ["sd", "I", "Monolith vs microservices?", "Monolith: one deployable; simple to build, test and debug; scales as one unit.|Microservices: independent services per business capability with their own data; independent deploy and scale, team autonomy.|Costs: network calls, distributed data, observability and DevOps overhead.|Start with a modular monolith; split when team or scaling needs justify it.", "Monolith = one big ship; microservices = a fleet of boats that need radios.", "monomicro"],
  ["sd", "A", "Design a patient randomization service for a clinical trial.", "API: POST /studies/{id}/subjects/{id}/randomize with an idempotency key; only authorised site users.|Logic: load the study's randomization scheme (blocked or stratified lists), allocate the next slot in a DB transaction with locking so two sites never get the same slot.|Then trigger drug kit assignment from site inventory, publish a SubjectRandomized event, and write an immutable audit record.|Non-functional: blinding (treatment arm hidden from most roles), high availability, full audit trail, validated behaviour.", "Check, Lock, Allocate, Assign kit, Audit, Announce.", "rand"],
  ["sd", "A", "Design drug supply and shipment tracking.", "Services: Inventory (depots and sites), Resupply (rules that trigger shipments when site stock falls below thresholds), Shipment (status lifecycle), Vendor integration.|Events over Kafka/RabbitMQ: KitAssigned, StockLow, ShipmentCreated, ShipmentDelivered.|Depot vendors exchange files via SFTP or APIs; an integration service parses, validates and updates status idempotently.|Track expiry dates and temperature excursions; dashboards and alerts for stock-outs.", "Stock drops, rule fires, shipment travels, vendor confirms.", "supply"],
  ["sd", "A", "Design a scalable CSV bulk import for clinical study data.", "Upload file to S3 (presigned URL) or API; create an import job and return 202 with a job id.|A worker streams and parses rows, validates schema and business rules, and collects per-row errors.|Write valid rows in batches inside transactions; decide all-or-nothing vs partial import with the business.|Report status and an error file; keep an audit trail of who imported what. Make it idempotent with a file hash.", "Upload, Queue, Parse, Validate, Write, Report.", "csv"],
  ["sd", "I", "What is the API gateway pattern and backend-for-frontend?", "One entry point in front of microservices for routing, auth, rate limiting, TLS and request aggregation.|Backend-for-frontend: a gateway or thin service per client type (web, mobile) shaping data for it.|Keep business logic out of the gateway.|On AWS: API Gateway or ALB; in code: YARP or Ocelot for .NET.", "Gateway = front desk; BFF = a personal assistant for each client."],
  ["sd", "I", "Explain the CAP theorem.", "In a distributed system with a network partition you must choose Consistency or Availability.|CP: refuse or delay requests to stay correct (for example allocation of limited drug kits).|AP: always answer, possibly stale, then reconcile (for example dashboards, notifications).|Most systems mix: strong consistency for critical writes, eventual consistency elsewhere.", "When the phone line is cut: wait for confirmation (C) or answer anyway (A)."],
  ["sd", "A", "What is the saga pattern?", "A long business transaction across services is split into local transactions, each publishing an event.|If a step fails, compensating actions undo earlier steps (cancel shipment, release kit).|Choreography: services react to events; orchestration: a coordinator tells each service what to do.|Needs idempotency, timeouts and clear states.", "Saga = travel booking: if the hotel fails, cancel the flight.", "saga"],
  ["sd", "A", "Design an audit trail for a GxP system.", "Record who, what, when, where and why for every create, update and delete, with old and new values.|Append-only and tamper-evident; time-synchronised; users cannot edit or delete audit records.|Capture via EF Core SaveChanges interceptor or DB triggers, plus business events.|Searchable for inspections; retained per regulation (21 CFR Part 11 style electronic records and signatures).", "Audit trail = CCTV for data: always on, never edited."],
  ["sd", "I", "How would you design rate limiting?", "Algorithms: fixed window, sliding window, token bucket (allows bursts), concurrency limits.|Apply per client, user or API key at the gateway (API Gateway throttling) and in app (ASP.NET Core rate limiting middleware).|For multiple instances use a shared store (Redis) for counters.|Return 429 with Retry-After.", "Token bucket: coins refill steadily; each request spends one."],
  ["sd", "A", "Design the deployment orchestration platform you built (as a system design question).", "Clients: AI hosts (Cursor, Claude, Copilot) talk MCP to the server over stdio or HTTP.|The server wraps Azure DevOps Server REST APIs: builds, releases, environments, plus node-level deployment steps.|Orchestration: a deployment plan per environment runs steps across nodes, polls status, retries safe steps, and stops on failure with a clear report.|Cross-cutting: user's credentials, approvals before production, logs of every action, structured outputs for the agent.", "Agent asks, MCP translates, Azure DevOps executes, humans approve.", "deploysys"],
  ["sd", "I", "How do you design for high availability?", "Remove single points of failure: multiple instances across availability zones behind a load balancer.|Managed databases with Multi-AZ failover and backups; health checks and auto-replacement.|Graceful degradation, timeouts, retries and circuit breakers between services.|Test failover and define RTO/RPO with the business.", "Two of everything, in two places, with a referee (load balancer)."],
];

